type PageViewPayload = {
  path: string;
  viewedAt: string;
};

export async function logPageView(payload: PageViewPayload): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT;

  if (!endpoint) {
    console.info('ANALYTICS_ENDPOINT is not set; skipping page view log.');
    return;
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'content-type': 'application/json'
    },
    body: JSON.stringify(payload),
    cache: 'no-store'
  });

  if (!response.ok) {
    throw new Error();
  }
}
